task.script:
{
    person = name -> all(`tl.accounts:Person`)
        .filter(p -> $p.get(`tl.accounts:Person#name`) == $name)
        .singleElement();
    group = name -> all(`tl.accounts:Group`)
        .filter(g -> $g.get(`tl.accounts:Group#name`) == $name)
        .singleElement();

    // Adds a value to a multi-valued reference unless already present (idempotent).
    addIfMissing = obj -> attr -> value ->
        $obj.get($attr).containsElement($value)
            ? "unchanged"
            : { $obj.add($attr, $value); log("SecurityTestSetup: added " + $value + " to " + $obj); "added" };

    // --- ADAPT: the tenant / scope the test users work in -------------------------------------
    tenant = all(`app.core:Tenant`)
        .filter(t -> $t.get(`app.core:Tenant#name`) == "Test")
        .singleElement();

    // --- ADAPT: role assignments (the references the assignment role rules read) --------------
    log("SecurityTestSetup: assignments");
    $addIfMissing($tenant, `app.core:Tenant#planners`, $person("T_PLANNER"));
    $addIfMissing($tenant, `app.core:Tenant#readers`, $person("T_READER"));
    $addIfMissing($group("SYSADMIN"), `tl.accounts:Group#members`, $person("T_SYSADMIN"));

    // --- ADAPT: minimal test data, resolved/created WITHIN the tenant -------------------------
    // e.g. one business object per role carrier type, one object in a second tenant (must stay invisible).

    // --- Verification: which test user holds which role on which objects ---------------------
    log("SecurityTestSetup: verification");
    check = label -> objects -> role -> user -> log("SecurityTestSetup: " + $user + " "
        + $role + " on " + $label + ": "
        + $objects.filterPermission("SecurityStructure." + $role, $user).size()
        + "/" + $objects.size());
    $check("tenant", [$tenant], "PLANNER", "T_PLANNER");
    $check("tenant", [$tenant], "READER", "T_READER");
    $check("orders", all(`app.core:Order`), "PLANNER", "T_PLANNER");
}
